import fs from 'node:fs'
import crypto from 'node:crypto'
import ts from 'typescript'
import { describeOracleCleanupError } from '../packages/db/tests/oracle-cleanup.ts'

const cases = [
  ['ordinary', () => new Error('detached failure')],
  ['null-prototype', () => Object.create(null)],
  ['throwing-conversion', () => new Proxy({}, { get() { throw new Error('conversion failed') } })],
  ['cyclic-aggregate', () => { const error = new AggregateError([], 'detached cycle'); error.errors.push(error); return error }],
]
const paths = [
  ['node', 'packages/db-adapter-conformance/tests/neon/neon-initial-receipt-worker.ts'],
  ['browser', 'packages/db-adapter-conformance/tests/neon/neon-receiving.ts'],
]
const results = []
for (const [host, path] of paths) {
  const text = fs.readFileSync(path, 'utf8')
  const file = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true)
  let callback
  const visit = node => {
    if (host === 'node' && ts.isCallExpression(node) && node.expression.getText(file) === 'process.on' && node.arguments[0]?.getText(file) === '`unhandledRejection`') callback = node.arguments[1]
    if (host === 'browser' && ts.isVariableDeclaration(node) && node.name.getText(file) === 'record') callback = node.initializer
    ts.forEachChild(node, visit)
  }
  visit(file)
  if (!callback) throw new Error(`No actual callback found in ${path}`)
  const body = ts.transpileModule(`return (${callback.getText(file)})`, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.None } }).outputText
  for (const [name, create] of cases) {
    const errors = []
    let prevented = false
    let failure
    try {
      const handler = new Function('describeOracleCleanupError', 'errors', 'detached', body)(describeOracleCleanupError, errors, errors)
      const reason = create()
      handler(host === 'node' ? reason : { reason, preventDefault() { prevented = true } })
      if (errors.length !== 1 || !errors[0] || (host === 'browser' && !prevented)) throw new Error('Detached diagnostic or browser handling lost')
    } catch (error) { failure = String(error) }
    results.push({host, path, source: crypto.createHash('sha256').update(text).digest('hex'), case:name, verdict: failure ? 'FAIL' : 'PASS', errors, ...(failure ? {failure} : {})})
  }
}
console.log(JSON.stringify(results, null, 2))
process.exitCode = results.some(result => result.verdict === 'FAIL') ? 1 : 0

