import fs from 'node:fs'
import ts from 'typescript'
import crypto from 'node:crypto'
import { describeOracleCleanupError } from '../packages/db/tests/oracle-cleanup.ts'
const phase=process.argv[2]??'repaired'
const path='packages/db-adapter-conformance/tests/eager-live-source-framework-oracle.ts'
const source=phase==='original'?JSON.parse(fs.readFileSync('.review-2377/cleanup-diagnostic-original-sources.json','utf8'))[path]:fs.readFileSync(path,'utf8')
const file=ts.createSourceFile(path,source,ts.ScriptTarget.Latest,true)
const node=file.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='observeEagerLiveSourceHistory')
const body=ts.transpileModule(`return (${node.getText(file).replace('export ','')})`,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.None}}).outputText
class ConformanceViolation extends Error { law='original law'; step=7;expected=['expected'];actual=['wrong'] }
const cases=[['ordinary',()=>new Error('secondary')],['null-prototype',()=>Object.create(null)],['throwing-conversion',()=>({toString(){throw new Error('conversion')}})],['throwing-prototype',()=>new Proxy({}, {getPrototypeOf(){throw new Error('prototype')}})],['cyclic-aggregate',()=>{const e=new AggregateError([],'cycle');e.errors.push(e);return e}],['throwing-aggregate-details',()=>Object.defineProperty(new AggregateError([],'details'),'errors',{get(){throw new Error('details')}})]]
const results=[]
for(const [label,make] of cases){
 const primary=new ConformanceViolation()
 const error=new AggregateError([make()],'comparison and cleanup',{cause:primary})
 const observe=new Function('ConformanceViolation','checkEagerLiveSourceHistory','describeOracleCleanupError',body)(ConformanceViolation,()=>Promise.reject(error),describeOracleCleanupError)
 let failure
 try{
  const raw=await observe({},[])
  if(raw.failure?.law!==primary.law||raw.failure.step!==7||raw.failure.actual!==primary.actual||!raw.failure.cleanup[0])throw new Error('Primary or cleanup diagnostic lost')
 }catch(error){failure=describeOracleCleanupError(error)}
 results.push({case:label,verdict:failure?'FAIL':'PASS',...(failure?{failure}:{})})
}
for(const [label,error] of [['raw-proxy',new Proxy({}, {getPrototypeOf(){throw new Error('classification')}})],['raw-aggregate-cause',Object.defineProperty(new AggregateError([],'unknown'),'cause',{get(){throw new Error('cause getter')}})]]){
 const observe=new Function('ConformanceViolation','checkEagerLiveSourceHistory','describeOracleCleanupError',body)(ConformanceViolation,()=>Promise.reject(error),describeOracleCleanupError)
 const outcome=await observe({},[]).catch(reason=>reason)
 results.push({case:label,verdict:outcome===error?'PASS':'FAIL',...(outcome===error?{}:{failure:'Original thrown value replaced during diagnostic classification'})})
}
console.log(JSON.stringify({path,source:crypto.createHash('sha256').update(source).digest('hex'),results},null,2))
process.exitCode=results.some(x=>x.verdict==='FAIL')?1:0
